// Push gate: decides whether the agent may send a push to a user right now.
// It never sends anything. History is in memory, one independent store per gate.

const HHMM = /^([01]\d|2[0-3]):([0-5]\d)$/;
const formatters = new Map();

function localParts(date, timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
    formatters.set(timeZone, f);
  }
  const p = {};
  for (const { type, value } of f.formatToParts(date)) p[type] = value;
  return {
    day: `${p.year}-${p.month}-${p.day}`,
    minutes: Number(p.hour) * 60 + Number(p.minute),
  };
}

function parseMinutes(s) {
  const m = typeof s === 'string' ? HHMM.exec(s) : null;
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

const deny = (reason) => ({ allowed: false, reason });

export function createPushGate() {
  // user id -> timestamps (ms) of pushes this gate allowed
  const sent = new Map();

  return {
    attempt(user, now) {
      if (!user || typeof user.id !== 'string' || user.id === '') return deny('invalid_user');
      if (!(now instanceof Date) || Number.isNaN(now.getTime())) return deny('invalid_time');

      // Unknown or invalid settings are held, never guessed.
      let zone;
      try {
        if (typeof user.timeZone !== 'string' || user.timeZone === '') throw new Error();
        zone = localParts(now, user.timeZone);
      } catch {
        return deny('invalid_time_zone');
      }
      const start = parseMinutes(user.quietStart);
      const end = parseMinutes(user.quietEnd);
      if (start === null || end === null) return deny('invalid_quiet_hours');
      const cap = user.dailyCap;
      if (!Number.isInteger(cap) || cap < 0) return deny('invalid_daily_cap');

      // Quiet window includes its start minute, excludes its end minute.
      // start > end wraps past midnight. start === end means no quiet window.
      const t = zone.minutes;
      const quiet = start < end ? t >= start && t < end : start > end ? t >= start || t < end : false;
      if (quiet) return deny('quiet_hours');

      // "Day" is the user's own calendar day in their current time zone.
      const history = sent.get(user.id) ?? [];
      let today = 0;
      for (const ts of history) {
        if (localParts(new Date(ts), user.timeZone).day === zone.day) today++;
      }
      if (today >= cap) return deny('daily_cap_reached');

      history.push(now.getTime());
      sent.set(user.id, history);
      return { allowed: true, reason: null };
    },
  };
}

import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/ours-g2-3/bot.mjs';

const u = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const at = (s) => new Date(s);
let g = createPushGate();
// Tokyo 12:00 = 03:00Z
assert.deepEqual(g.attempt(u, at('2026-10-23T03:00:00Z')), { allowed: true, reason: null });
// Tokyo 22:00 start inclusive (13:00Z), 06:59 quiet, 07:00 allowed
assert.equal(g.attempt(u, at('2026-10-23T13:00:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(u, at('2026-10-22T21:59:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(u, at('2026-10-22T22:00:00Z')).allowed, true); // 07:00 JST Oct 23
// cap: 2 sent on Oct 23 JST so far; third ok, fourth blocked
assert.equal(g.attempt(u, at('2026-10-23T05:00:00Z')).allowed, true);
assert.equal(g.attempt(u, at('2026-10-23T06:00:00Z')).reason, 'daily_cap_reached');
// next local day resets (Oct 24 08:00 JST)
assert.equal(g.attempt(u, at('2026-10-23T23:00:00Z')).allowed, true);
// independent gates
assert.equal(createPushGate().attempt(u, at('2026-10-23T06:00:00Z')).allowed, true);
// day boundary uses user zone: LA user, 23:30 PDT Oct 22 vs 00:30 Oct 23 are different days
const la = { id: 'u2', timeZone: 'America/Los_Angeles', quietStart: '23:00', quietEnd: '07:00', dailyCap: 1 };
g = createPushGate();
assert.equal(g.attempt(la, at('2026-10-22T20:00:00Z')).allowed, true); // 13:00 PDT
assert.equal(g.attempt(la, at('2026-10-22T21:00:00Z')).reason, 'daily_cap_reached');
assert.equal(g.attempt(la, at('2026-10-23T20:00:00Z')).allowed, true); // next day
// same-day window, no wrap
const d = { ...u, id: 'u3', quietStart: '12:00', quietEnd: '13:00' };
assert.equal(g.attempt(d, at('2026-10-23T03:00:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(d, at('2026-10-23T04:00:00Z')).allowed, true);
// denied does not count; cap 0; bad inputs
g = createPushGate();
assert.equal(g.attempt({ ...u, dailyCap: 0 }, at('2026-10-23T03:00:00Z')).reason, 'daily_cap_reached');
assert.equal(g.attempt({ ...u, timeZone: 'Nope/Zone' }, at('2026-10-23T03:00:00Z')).reason, 'invalid_time_zone');
assert.equal(g.attempt({ ...u, quietStart: '25:00' }, at('2026-10-23T03:00:00Z')).reason, 'invalid_quiet_hours');
console.log('ok');
